"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {statementMinor} from '@/lib/cashier-bank-statement-request';
import {checkedBankMatch,bankMatchArgs,readBankMatchReceipt,type BankMatchRequest} from '@/lib/cashier-bank-match-request';
import {readMatchSources} from '@/lib/cashier-bank-reconciliation';
export function CashierBankMatchCreate({scope,account,onSaved}:{scope:HandoffScope;account:string;onSaved:()=>void}){
 const key='irp.bank.match.v1:'+ [scope.tenant,scope.property,scope.actor,account].join(':');
 const [pending,setPending]=useState<BankMatchRequest|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);
 function read(){const raw=sessionStorage.getItem(key);if(raw===null)return null;const r=checkedBankMatch(JSON.parse(raw));if(r.account!==account)throw Error('Pending match account changed.');return r}
 useEffect(()=>{alive.current=true;try{setPending(read())}catch(e){setError(e instanceof Error?e.message:'Unable to recover match.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen match entry.')}
 async function save(request:BankMatchRequest,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const r=checkedBankMatch(request);if(r.account!==account)throw Error('Match account changed.');await identify();if(!alive.current)return;const prior=read(),encoded=JSON.stringify(r);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Recover the pending match first.');sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve match recovery.');setPending(r);
  const value=await hotelRpc(status?'cashier_bank_reconciliation_status':'match_cashier_bank_deposit',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.id,p_kind:'match'}:bankMatchArgs(r,scope));await identify();if(!alive.current)return;
  if(!readBankMatchReceipt(value,r,scope,status)){setMessage('No saved match found. Retry the original entry.');return}
  const current=read();if(current&&JSON.stringify(current)!==encoded)throw Error('A different match is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear match recovery.');setPending(null);setDeposits(null);setCredits(null);setMessage('Match item recorded for manual reconciliation.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Match interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 const [deposits,setDeposits]=useState<ReturnType<typeof readMatchSources>|null>(null),[credits,setCredits]=useState<ReturnType<typeof readMatchSources>|null>(null);
 async function sources(kind:'deposit'|'credit',next=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await identify();const before=next?(kind==='deposit'?deposits:credits)?.next??null:null;const page=readMatchSources(await hotelRpc('cashier_bank_match_sources',{p_tenant:scope.tenant,p_property:scope.property,p_account:account,p_kind:kind,p_before:before}),scope,account,kind,before);await identify();if(alive.current){if(kind==='deposit')setDeposits(page);else setCredits(page)}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load eligible records.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 const [cancelConfirmed,setCancelConfirmed]=useState(false);
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending.id;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const v=await hotelRpc('cancel_cashier_reconciliation_action',{p_tenant:scope.tenant,p_property:scope.property,p_request:request,p_kind:'match',p_confirmed:true}) as Record<string,unknown>;await identify();if(!alive.current)return;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==request||v.kind!=='match'||v.cancelled!==true||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Cancellation receipt does not match the pending request.');const current=read();if(current&&current.id!==request)throw Error('A different request is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear cancelled request.');setPending(null);setCancelConfirmed(false);setMessage('Unsaved request cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm its result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section><h3>Match a deposit</h3>{pending?<><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this unsaved request.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel pending request</button><p>Pending match: {pending.reason}</p><button disabled={busy} onClick={()=>void save(pending)}>Retry bank match</button><button disabled={busy} onClick={()=>void save(pending,true)}>Check bank match</button></>:<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),deposit=deposits?.entries.find(x=>x.id===f.get('deposit')),credit=credits?.entries.find(x=>x.id===f.get('credit')),amount=statementMinor(String(f.get('amount')).trim(),'credit');if(!deposit||!credit)throw Error('Choose a deposit and statement credit.');if(BigInt(amount)>BigInt(deposit.remaining)||BigInt(amount)>BigInt(credit.remaining))throw Error('Amount exceeds the remaining deposit or credit.');if(credit.date<deposit.date)throw Error('Statement credit predates the deposit.');void save({id:crypto.randomUUID(),account,deposit:deposit.id,statement:credit.id,amount,reason:String(f.get('reason')).trim()})}catch(e){setError(e instanceof Error?e.message:'Review match details.')}}}><fieldset disabled={busy}>{(['deposit','credit'] as const).map(kind=>{const page=kind==='deposit'?deposits:credits;return <div key={kind}><button type="button" onClick={()=>void sources(kind)}>Refresh {kind==='deposit'?'eligible deposits':'eligible credits'}</button><label>{kind==='deposit'?'Deposit to match':'Statement credit to match'}<select key={page?.entries.map(e=>e.id).join(':')??'empty'} name={kind} required defaultValue=""><option value="">Choose a record</option>{page?.entries.map(e=><option key={e.id} value={e.id}>{e.date} - {e.reference} - {usd(Number(e.remaining))} remaining</option>)}</select></label>{page?.next&&<button type="button" onClick={()=>void sources(kind,true)}>Next {kind} page</button>}</div>})}<label>Match amount<input name="amount" inputMode="decimal" required/></label><label>Match explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm these records and the match amount.</label><button>Record bank match</button></fieldset></form>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}
